import { createI18n, defineMessages } from "@usevibejs/i18n";
const en = defineMessages({ welcome: "Welcome, {name}!", save: "Save" });
export const i18n = createI18n({
  locale: "en",
  fallbackLocale: "en",
  messages: { en, tr: { welcome: "Hoş geldin, {name}!", save: "Kaydet" } },
});
await i18n.ready;
createApp(App).use(i18n).mount("#app");

const i18n = createI18n({
  locale: "en",
  fallbackLocale: "en",
  messages: { en: { navigation: { home: "Home" } } },
  namespaces: { en: { billing: { total: "Total" } } },
  loaders: {
    tr: {
      default: () => import("./locales/tr.json"),
      billing: () => import("./locales/tr-billing.json"),
    },
  },
});
await i18n.preload("tr", ["billing"]);
i18n.register("en", { total: "Updated total" }, "billing", "merge");
i18n.dynamic("billing:total");

n(1234.56);
n(0.35, { style: "percent" });
n(1200, { notation: "compact" });
n(1234.56, { style: "currency", currency: "USD", currencyDisplay: "narrowSymbol" });
n(12, { style: "unit", unit: "kilometer" });

const i18n = createI18n({ locale: "en", timeZone: "Europe/Istanbul", messages: { en } });
i18n.d(new Date(), { dateStyle: "long", timeStyle: "short" });
i18n.d(timestamp, { hour: "2-digit", hourCycle: "h23", timeZone: "UTC" });
i18n.dateRange(start, end, { dateStyle: "medium" });

rt(-5, "minute");
rt(-1, "day", { numeric: "auto" });
list(["Apple", "Banana", "Orange"], { type: "conjunction" });
i18n.compare("Élodie", "Cem", { sensitivity: "base", numeric: true });

{
  "sourceLocale": "en",
  "resources": [{ "locale": "en", "file": "locales/en.json" }],
  "output": "src/messages.gen.d.ts"
}

const child = createLocaleContext({
  locale: "ar",
  fallbackLocale: "en",
  messages: { ar: { hello: "مرحباً" }, en: { hello: "Hello" } },
});

import { connectI18nRouter } from "@usevibejs/i18n/router";
const localization = connectI18nRouter(router, i18n, { namespaces: ["default", "billing"] });
await localization.setLocale("tr");
app.onUnmount(localization.stop);
